head.script:
scwin.init = function() {
	for (var i = 0; i < 30; i++) {
		scwin.itemsetData.push("label=" + i);
		scwin.itemsetData.push(i + "");
	}
	dataList2.setData(scwin.itemsetData.slice(0));
	dataList3.setData(scwin.itemsetData.slice(0));
	dataList4.setData(scwin.itemsetData.slice(0));
	dataList1.setData(scwin.data1.slice(0));
}
scwin.grid1_ongroupby = function(options) {
	options.rowNumHeader = {
		inputType: 'expression',
		expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
		align: 'left',
		colSpan: 5
	};
	options.rowNumFooter = {
		colSpan: 3
	};
	options.rowStatusFooter = {
		value: '합계'
	};
	options.groupbyFooter = [{
		inputType: 'expression',
		expression: 'SUM("col3")'
	}];
	this.groupby(options);
	return true;
}
scwin.grid1_groupbyFilterBoxFormatter = function(data, isGroupby) {
	var label = "";
	var labelArr = [];
	var groupbyStr = isGroupby ? "(groupby)" : "";
	for (var i = 0; i < data.length; i++) {
		var s_label = "";
		var obj = data[i];
		var header = obj.header;
		var filter = obj.filter;
		if (filter.length === 0) {
			s_label = "-null-";
		} else {
			for (var j = 0; j < filter.length; j++) {
				if (filter[j].gate) {
					s_label = s_label + " " + filter[j].gate + " ";
				}
				// var values = filter[j].values;
				var labels = filter[j].labels; // filter[j].values를 할 경우 value를, labels를 참조할 경우 label을 가져온다.
				if (labels.join) {
					labels = "[" + labels.join(" ,") + "]";
				}
				s_label = s_label + filter[j].operator + " " + labels;
			}
		}
		s_label = "(" + header + " " + s_label + ")";
		labelArr.push(s_label);
	}
	label = groupbyStr + labelArr.join(" & ");
	return label;
};
